(async function () {
    let collection = ZoteroPane.getSelectedCollection();

    if (!collection) {
        Zotero.alert(null, "提示", "请先在左侧选中一个目录（collection）");
        return;
    }

    let colID = collection.id;

    // 获取当前库所有条目
    let libraryID = collection.libraryID;
    let items = await Zotero.Items.getAll(libraryID);

    let count = 0;

    for (let item of items) {
        if (!item.isRegularItem()) continue;

        let cols = item.getCollections();

        if (cols.includes(colID)) {
            // 清空 tags
            item.setTags([]);
            await item.saveTx();
            count++;
        }
    }

    Zotero.alert(null, "完成", `已清空 ${count} 个条目的 tags`);
})();

