// --- System Prompts ---
const OPTIMIZE_SYSTEM_PROMPT = `You are an expert AI prompt engineer. Your task is to refine and polish the user's input into a high-quality, descriptive image generation prompt. 
Requirements:
1. Style: Classical Chinese ink wash painting, minimalist, traditional aesthetic.
2. Focus: Composition, lighting, atmosphere (misty, zen, ethereal), and empty space for calligraphy.
3. Language: Output ONLY the optimized prompt in English.
4. Goal: Make it highly suitable for high-end AI image generation.`;

const RANDOM_GEN_SYSTEM_PROMPT = `You are a creative director for classical Chinese art. 
Task: Based on the provided poem context, generate a UNIQUE and POETIC image generation prompt for a poster background.
Requirements:
1. Style: Traditional Chinese art (ink wash, watercolor, or minimalist brushwork).
2. Content: Interpret the mood of the poem visually.
3. Language: Output ONLY the prompt text in English.
4. Format: Descriptive, focusing on visual elements.`;

export const Prompt: React.FC<PromptProps> = ({ onGenerate, currentPoem, isGenerating, setIsGenerating }) => {
  const [prompt, setPrompt] = useState('');
  const [isExpanded, setIsExpanded] = useState(true);
  const [history, setHistory] = useState<PromptHistoryItem[]>([]);
  const [showHistory, setShowHistory] = useState(false);
  const [isOptimizing, setIsOptimizing] = useState(false);
  const [isGeneratingRandom, setIsGeneratingRandom] = useState(false);

  const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY || '' });

  // Load history from IndexedDB on mount
  useEffect(() => {
    const loadHistory = async () => {
      try {
        const savedHistory = await get<PromptHistoryItem[]>('prompt_history');
        if (savedHistory) {
          setHistory(savedHistory);
        }
      } catch (e) {
        console.error("Failed to load history from IndexedDB", e);
      }
    };
    loadHistory();
  }, []);

  // Save history to IndexedDB when it changes
  useEffect(() => {
    const saveHistory = async () => {
      try {
        await set('prompt_history', history);
      } catch (e) {
        console.error("Failed to save history to IndexedDB", e);
      }
    };
    if (history.length > 0 || localStorage.getItem('prompt_history_initialized')) {
      saveHistory();
      localStorage.setItem('prompt_history_initialized', 'true');
    }
  }, [history]);

  const handleRandomPrompt = async () => {
    setIsGeneratingRandom(true);
    try {
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `Poem: ${currentPoem.title} by ${currentPoem.author}`,
        config: { systemInstruction: RANDOM_GEN_SYSTEM_PROMPT }
      });
      const generatedPrompt = response.text?.trim() || '';
      setPrompt(generatedPrompt);
    } catch (error) {
      console.error("Failed to generate random prompt:", error);
    } finally {
      setIsGeneratingRandom(false);
    }
  };

  const handleOptimizePrompt = async () => {
    if (!prompt) return;
    setIsOptimizing(true);
    try {
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `User Prompt: ${prompt}\nContext: Background for poem "${currentPoem.title}"`,
        config: { systemInstruction: OPTIMIZE_SYSTEM_PROMPT }
      });

      const optimizedText = response.text?.trim() || '';
      setPrompt(optimizedText);
    } catch (error) {
      console.error("Failed to optimize prompt:", error);
    } finally {
      setIsOptimizing(false);
    }
