make_dt <- function(data, scrollX=FALSE, ordering=FALSE, heat_cols=NULL, n_bins=6) {

  dt <- datatable(
    data,
    rownames=FALSE,
    selection="none",
    options=list(
      dom=if(scrollX)"ft" else "t",
      scrollX=scrollX,
      ordering=ordering
    )
  )

  if(!is.null(heat_cols)) {
    for(col in heat_cols) {

      x <- data[[col]]
      if(!is.numeric(x)) next
      if(all(is.na(x))) next

      brks <- unique(seq(min(x, na.rm=TRUE), max(x, na.rm=TRUE), length.out=n_bins))
      brks <- sort(brks)
      if(length(brks) < 2) next

      cols <- colorRampPalette(c("#fee2e2","#fca5a5","#60a5fa","#1d4ed8"))(length(brks)+1)

      dt <- dt %>% formatStyle(
        col,
        backgroundColor = styleInterval(brks, cols)
      )
    }
  }

  dt
}

library(reactable)
library(htmltools)
library(dplyr)

# Use mtcars dataset and create aggregated summary
df_plot2 <- mtcars %>%
  group_by(cyl) %>%
  summarise(
    valid_est = mean(mpg),      # Valid estimate (like your valid_est)
    model_est = mean(hp),       # Model estimate (like your model_est)
    overlap = ifelse(mean(mpg) > 20 & mean(hp) < 150, TRUE, FALSE)  # Overlap condition
  ) %>%
  mutate(
    compare = ""  # Empty column for the comparison bar
  )

# The bar_compare function (unchanged)
bar_compare <- function(valid, model, overlap) {

  if (is.na(valid) || is.na(model)) {
    return(div("Missing"))
  }

  maxv <- max(valid, model)

  vw <- valid / maxv * 100
  mw <- model / maxv * 100

  bg <- ifelse(
    is.na(overlap), "#f3f4f6",
    ifelse(overlap, "#ecfdf5", "#fef2f2")
  )

  div(
    style = paste0(
      "width:220px;height:36px;background:", bg,
      ";border-radius:6px;position:relative;padding:4px;"
    ),

    div(style = paste0(
      "position:absolute;top:7px;left:4px;height:10px;
       width:", vw, "%;background:#2563eb;border-radius:4px;"
    )),

    div(style = paste0(
      "position:absolute;top:20px;left:4px;height:10px;
       width:", mw, "%;background:#dc2626;border-radius:4px;"
    ))
  )
}

# Create the reactable
reactable(df_plot2,
          columns = list(
            cyl = colDef(name = "Cylinders", width = 100),
            valid_est = colDef(name = "MPG (Valid)", width = 120, 
                               format = colFormat(digits = 1)),
            model_est = colDef(name = "HP (Model)", width = 120,
                               format = colFormat(digits = 0)),
            overlap = colDef(
              name = "Overlap", width = 80,
              cell = function(v) {
                bg = if(is.na(v)) "#f3f4f6" else if(v) "#ecfdf5" else "#fef2f2"
                txt = if(is.na(v)) "NA" else if(v) "✓" else "✗"
                div(style = paste0("background:", bg, ";padding:4px 8px;border-radius:6px;font-weight:600;text-align:center;"), txt)
              }
            ),
            compare = colDef(name = "MPG vs HP", width = 500, html = TRUE,
                             cell = function(value, index) {
                               row <- df_plot2[index,]
                               bar_compare(row$valid_est, row$model_est, row$overlap)
                             }
            )
          ),
          width = "100%",
          fullWidth = TRUE,
          pagination = FALSE,
          resizable = TRUE,
          striped = TRUE,
          bordered = TRUE,
          highlight = TRUE
)
